      const bu = await prisma.businessUnit.create({ data: {
        mantenedoraId: tenant.mantenedora.id, setorId: (await prisma.businessUnit.findUniqueOrThrow({ where: { id: tenant.businessUnit.id }, select: { setorId: true } })).setorId,
        name: `BCI unit ${repetition}`, phone: `5586${String(10000000 + repetition)}`,
      } });
      await prisma.userBuRole.create({ data: { userId: tenant.owner.id, buId: bu.id, role: 'ADMIN', grantedViaTipo: 'DIRETO' } });
      const key = `0000000${repetition + 1}-0000-4000-8000-00000000000${repetition + 1}`;
      const payload = { buId: bu.id, tipo: 'OFICIAL', operation: 'NOVO' };
      const createResults = await Promise.all(Array.from({ length: 20 }, () => request(app.getHttpServer())
        .post('/api/bff/number-registrations').set('Cookie', cookie).set('x-requested-with', 'bci')
        .set('Idempotency-Key', key).send(payload)));
      expect(createResults.every((result) => result.status === 201)).toBe(true);
      const attemptIds = new Set(createResults.map((result) => result.body.attempt?.id));
      const nonces = new Set(createResults.map((result) => result.body.nonce));
      expect(attemptIds.size).toBe(1);
      expect(nonces.size).toBe(1);
      const attemptId = createResults[0].body.attempt.id as string;
      expect(await prisma.channelRegistrationAttempt.count({ where: { mantenedoraId: tenant.mantenedora.id, idempotencyKey: key } })).toBe(1);
      await request(app.getHttpServer()).post('/api/bff/number-registrations').set('Cookie', cookie).set('x-requested-with', 'bci')
        .set('Idempotency-Key', key).send({ ...payload, tipo: 'NAO_OFICIAL' }).expect(409).expect(({ body }) => expect(body.code).toBe('IDEMPOTENCY_CONFLICT'));
      await request(app.getHttpServer()).post(`/api/bff/number-registrations/${attemptId}/authorize`).set('Cookie', cookie).set('x-requested-with', 'bci')
        .send({ nonce: createResults[0].body.nonce, code: 'fixture-oauth-code' }).expect(200);

      let enterProvider!: () => void;
      let releaseProvider!: () => void;
      const providerEntered = new Promise<void>((resolve) => { enterProvider = resolve; });
      const providerGate = new Promise<void>((resolve) => { releaseProvider = resolve; });
