      const duplicateFinalizations = await Promise.all(Array.from({ length: 19 }, () => request(app.getHttpServer())
        .post(`/api/bff/number-registrations/${attemptId}/confirm`).set('Cookie', cookie).set('x-requested-with', 'bci')
        .send({ wabaId: '123456789', phoneNumberId: String(700000001 + repetition), modoRegistro: 'JA_REGISTRADO', after: 'fixture-page-1' })));
      expect(duplicateFinalizations.every((result) => result.status === 409)).toBe(true);
      releaseProvider();
      const winner = await winningConfirmation;
      expect(winner.status).toBe(200);
      expect(metaFake.confirmCalls).toBe(confirmCountBeforeWinner + 1);
      const promoted = await prisma.channelRegistrationAttempt.findUniqueOrThrow({ where: { id: attemptId } });
