      metaFake.wabaRecursos = [
        ...metaFake.wabaRecursos.filter((resource) => resource.phoneNumberId === String(700000001 + repetition)),
        ...metaFake.wabaRecursos.filter((resource) => resource.phoneNumberId !== String(700000001 + repetition)),
