      const identity = await prisma.providerResourceIdentity.findUniqueOrThrow({ where: { provider_externalResourceId: { provider: 'OFICIAL', externalResourceId: String(700000001 + repetition) } } });
      expect(identity.currentChannelId).toBe(replacement.body.attempt.channelId);
      operationCounts.push(createResults.length + duplicateFinalizations.length + 1);
      metaFake.confirmHook = null;
    }
    const evidence = { gate: 'BCI-DUPLICATE-SUBMIT-OR-REPLAY', severity: 'high', repetitions: operationCounts.length, operationsPerRepetition: operationCounts[0], operationCounts, createReplayWinnerCount: 5, providerIdentityQueries: metaFake.confirmCalls, mismatchedPayloadNegativeControls: 5, postPromotionStateChecked: true };
    console.log(`[BCI-EVIDENCE]${JSON.stringify(evidence)}`);
    expect(operationCounts).toEqual([40, 40, 40, 40, 40]);
    expect(metaFake.confirmCalls).toBe(15);
  });

