    const meio = { ...env, EVOLUTION_API_URL: 'http://evo:8080' } as NodeJS.ProcessEnv;
    expect(() => verificarConfiguracao(meio)).toThrow(/EVOLUTION_API_KEY/);

    const completo = { ...meio, EVOLUTION_API_KEY: 'chave', EVOLUTION_WEBHOOK_URL: 'https://api.example.test/webhooks/evolution', EVOLUTION_WEBHOOK_SECRET: 'fake-secret' } as NodeJS.ProcessEnv;
    expect(() => verificarConfiguracao(completo)).not.toThrow();
    expect(() => verificarConfiguracao({ ...completo, EVOLUTION_WEBHOOK_URL: 'https://api.example.test/webhooks/evolution/secret' } as NodeJS.ProcessEnv)).toThrow(/sem credenciais no path/);
