    expect(() => verificarConfiguracao({ ...fields, GRAPH_VERSION: 'v26' } as NodeJS.ProcessEnv)).toThrow(/vXX\.0/);
    expect(() => verificarConfiguracao({ ...fields, GRAPH_VERSION: 'v26.0' } as NodeJS.ProcessEnv)).not.toThrow();
    expect(() => verificarConfiguracao({ CHANNEL_CREDENTIAL_KEY_ID: 'fake' } as NodeJS.ProcessEnv)).toThrow(/CHANNEL_CREDENTIAL_KEY_ID/);
  });
});

