    await this.registro.registrar(tx, actor.mantenedoraId, key, { id: actor.id, nome: actor.nome, email: actor.email }, {
      buId: attempt.buId, entidadeId: attempt.id, detalhe: { attemptId: attempt.id, stage, provider: attempt.type },
