export function nomeConexaoProvedor(state: string | null | undefined): string {
  const nomes: Record<string, string> = {
    PENDING: 'aguardando confirmação', CONNECTED: 'conectado', VERIFIED: 'identidade confirmada',
    SUBSCRIBED: 'eventos ativados', IDENTITY_QUARANTINED: 'identidade em revisão',
    CLOSE: 'desconectado', CLOSED: 'desconectado', OPEN: 'conectado',
  };
  return state ? (nomes[state.toUpperCase()] ?? 'estado não confirmado') : 'pendente';
}

export function mensagemErroCadastro(error: unknown): string {
  const code = (error as { codigo?: unknown } | null)?.codigo;
  const mensagens: Record<string, string> = {
    ATTEMPT_STALE: 'Esta etapa mudou em outra sessão. Atualize a lista e abra a etapa atual.',
    AUTHORIZATION_AMBIGUOUS: 'A autorização não foi confirmada. O código não será reutilizado; encerre a tentativa para iniciar uma nova autorização.',
    MANUAL_RECOVERY_REQUIRED: 'O resultado de uma etapa externa ainda é incerto. Não repita a operação; peça uma revisão à instalação.',
    PARTIAL_CLEANUP_REQUIRED: 'Há uma etapa externa parcial que precisa ser revisada pela instalação antes de continuar.',
    CHANNEL_OPERATION_BUSY: 'Outra operação deste canal ainda está em andamento. Aguarde e atualize a lista.',
    GENERATION_CONFLICT: 'O canal mudou em outra sessão. Atualize a lista antes de continuar.',
  };
  if (typeof code === 'string' && mensagens[code]) return mensagens[code];
  return 'Não foi possível concluir esta etapa. Atualize a lista e tente novamente quando o estado estiver confirmado.';
}

