import { TentativaNumero } from './cadastroNumero';

export type OperacaoCadastro = 'reserva' | 'retomada' | 'autorizacao' | 'confirmacao' | 'acao' | 'pareamento' | 'verificacao' | 'opcoes';
export interface TokenOperacaoCadastro {
  readonly lifecycle: number;
  readonly sequence: number;
  readonly kind: OperacaoCadastro;
  readonly attemptId: string | null;
  readonly targetBuId?: string;
  readonly targetChannelId?: string;
}
export interface TokenLeituraTentativa {
  readonly lifecycle: number;
  readonly attemptId: string;
  readonly channelId: string | null;
  readonly generation: number;
}

/** Owns the single UI operation and monotonically commits server attempt DTOs. */
export class DonoCicloCadastro {
  private lifecycle = 0;
  private sequence = 0;
  private operation: TokenOperacaoCadastro | null = null;
  private current: TentativaNumero | null = null;

  invalidar(clearAttempt = true): number {
    this.lifecycle += 1;
    this.operation = null;
    if (clearAttempt) this.current = null;
    return this.lifecycle;
  }

  atual(): TentativaNumero | null { return this.current; }
  ciclo(): number { return this.lifecycle; }

  iniciar(kind: OperacaoCadastro, attemptId: string | null = this.current?.id ?? null): TokenOperacaoCadastro | null {
    if (this.operation) return null;
    if (attemptId && this.current?.id !== attemptId && kind !== 'retomada') return null;
    const token: TokenOperacaoCadastro = { lifecycle: this.lifecycle, sequence: ++this.sequence, kind, attemptId };
    this.operation = token;
    return token;
  }

  iniciarPareamento(buId: string, channelId: string | null): TokenOperacaoCadastro | null {
    if (this.operation) return null;
    const token: TokenOperacaoCadastro = {
      lifecycle: this.lifecycle, sequence: ++this.sequence, kind: 'pareamento', attemptId: null,
      targetBuId: buId, targetChannelId: channelId ?? undefined,
    };
    this.operation = token;
    return token;
  }

  possui(token: TokenOperacaoCadastro): boolean {
    return this.operation === token && token.lifecycle === this.lifecycle;
  }

  finalizar(token: TokenOperacaoCadastro): boolean {
    if (!this.possui(token)) return false;
    this.operation = null;
    return true;
  }

  tokenLeitura(): TokenLeituraTentativa | null {
    const attempt = this.current;
    return attempt ? { lifecycle: this.lifecycle, attemptId: attempt.id, channelId: attempt.channelId, generation: attempt.generation } : null;
  }

  /** Reservation is the only operation allowed to establish a different attempt. */
  reservar(attempt: TentativaNumero, token: TokenOperacaoCadastro): boolean {
    if (!this.possui(token) || token.kind !== 'reserva' || token.attemptId !== null) return false;
    this.current = attempt;
    return true;
  }

  /**
   * Action DTOs may legitimately advance generation/channel while reads may
   * only refresh the exact captured channel generation. In both cases older
   * versions are rejected and the attempt/BU identity must remain stable.
   */
  aplicar(attempt: TentativaNumero, token: TokenOperacaoCadastro, kind: 'acao' | 'retomada'): boolean {
    if (!this.possui(token) || (kind === 'acao' && token.attemptId !== attempt.id)) return false;
    if (kind === 'retomada' && token.kind !== 'retomada') return false;
    const current = this.current;
    if (current && (current.id !== attempt.id || current.buId !== attempt.buId || current.tipo !== attempt.tipo)) return false;
    if (current && (attempt.version < current.version || attempt.generation < current.generation)) return false;
    const authoritativeCancelDetach = kind === 'acao'
      && token.kind === 'acao'
      && attempt.state === 'CANCELLED'
      && attempt.stage === 'CANCELLED'
      && attempt.channelId === null;
    if (current?.channelId && attempt.channelId !== current.channelId && !authoritativeCancelDetach) return false;
    if (current?.state === 'CANCELLED' && attempt.channelId !== current.channelId) return false;
    this.current = attempt;
    return true;
  }

  observar(attempt: TentativaNumero, token: TokenLeituraTentativa): boolean {
    if (token.lifecycle !== this.lifecycle || !this.current || token.attemptId !== this.current.id) return false;
    if (attempt.id !== token.attemptId || attempt.buId !== this.current.buId || attempt.tipo !== this.current.tipo) return false;
    if (attempt.version < this.current.version || attempt.generation < this.current.generation) return false;
    if (attempt.channelId !== token.channelId || attempt.generation !== token.generation) return false;
    if (this.current.channelId && attempt.channelId !== this.current.channelId) return false;
    this.current = attempt;
    return true;
  }

  /** A pair response may advance attemptId only when the real safe BU projection confirms it. */
  adotarPareamento(
    attempt: TentativaNumero,
    token: TokenOperacaoCadastro,
    correlation: { buId: string; channelId: string; attemptId: string; generation: number },
    projection: { buId: string; channelId: string; currentAttemptId?: string | null; generation?: number } | undefined,
  ): boolean {
    if (!this.possui(token) || token.kind !== 'pareamento' || !projection) return false;
    if (token.targetBuId !== correlation.buId || (token.targetChannelId && token.targetChannelId !== correlation.channelId)) return false;
    if (attempt.id !== correlation.attemptId || attempt.buId !== correlation.buId || attempt.tipo !== 'NAO_OFICIAL' || attempt.channelId !== correlation.channelId || attempt.generation !== correlation.generation) return false;
    if (projection.buId !== correlation.buId || projection.channelId !== correlation.channelId || projection.currentAttemptId !== correlation.attemptId || projection.generation !== correlation.generation) return false;
    if (this.current && this.current.buId !== correlation.buId) return false;
    if (this.current?.id === attempt.id && attempt.version < this.current.version) return false;
    this.current = attempt;
    return true;
  }
}
