      await form.dispose();
      await expect(page.getByRole('button', { name: 'Cancelar tentativa' })).toBeVisible();

      if (wave === 0) {
        let releaseRead: (() => void) | undefined;
        const readBarrier = new Promise<void>((resolve) => { releaseRead = resolve; });
        let saved = false;
        let staleRequest: Request | undefined;
        await page.route((url) => url.origin === new URL(page.url()).origin && /\/api\/bff\/number-registrations\/[^/]+$/.test(url.pathname), async (route) => {
