    const finalCancelledStatus = await page.getByRole('status').filter({ hasText: 'Tentativa encerrada antes de efeitos externos' }).count();
    expect(finalCancelledStatus).toBe(1);
    console.log('[FRC-EVIDENCE] ' + JSON.stringify({ waves: 5, triggersPerWave: 20, totalSubmitTriggers, reservationRequestsPerWave: waveRequests, inFlightAtBarrier, maximumInFlight, staleControl: { fetchedStage: staleStage, realResponseFinished: staleResponseFinished, finalUiIsCancelled: finalCancelledStatus === 1 } }));
  });

