        data: { operationLeaseToken: leaseToken, operationLeaseUntil: new Date(now.getTime() + OPERATION_LEASE_MS) },
      });
      if (!lease.count) throw new ConflictException({ code: 'CHANNEL_OPERATION_BUSY' });
