    let verifiedPhone: string | null = null;
    let connectionOpen = false;
    if (tipo === 'OFICIAL') {
      if (!channel.wabaId || !channel.phoneNumberId) throw new ConflictException({ code: 'CHANNEL_IDENTITY_NOT_VERIFIED' });
